import{_ as e,o as t,c as i,a2 as r}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse('{"title":"D4.1 · Trigger 与主动收件箱","description":"Hearth D4.1 开发增量：Hearth 能提出可执行的主动建议，说明触发原因、建议动作、预算和是否会打扰用户。","frontmatter":{"title":"D4.1 · Trigger 与主动收件箱","description":"Hearth D4.1 开发增量：Hearth 能提出可执行的主动建议，说明触发原因、建议动作、预算和是否会打扰用户。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-4/d4-1.md","filePath":"delivery/stage-4/d4-1.md","lastUpdated":null}'),l={name:"delivery/stage-4/d4-1.md"};function d(h,a,s,o,n,c){return t(),i("div",null,[...a[0]||(a[0]=[r(`<p class="eyebrow">STAGE 4 · D4.1 · 1 / 5</p><h1 id="d4-1-·-trigger-与主动收件箱" tabindex="-1">D4.1 · Trigger 与主动收件箱 <a class="header-anchor" href="#d4-1-·-trigger-与主动收件箱" aria-label="Permalink to &quot;D4.1 · Trigger 与主动收件箱&quot;">​</a></h1><p class="lead">让系统先提出“现在可以做什么”，但每一次建议都要有来源、预算、打扰级别和明确暂停入口。</p><p class="page-meta">STAGE 4 · D4.1 · 1 个纵向切片 · 4 个工作包</p><div class="section-grid"><div><strong>用户可见结果</strong>Hearth 能提出可执行的主动建议，说明触发原因、建议动作、预算和是否会打扰用户。</div><div><strong>完成门槛</strong>重复事件不生成重复任务；主动建议有来源；用户能一键暂停；没有无限后台循环；预算耗尽会停止；高风险动作仍需审批。</div></div><h2 id="这一步要交付什么" tabindex="-1">这一步要交付什么 <a class="header-anchor" href="#这一步要交付什么" aria-label="Permalink to &quot;这一步要交付什么&quot;">​</a></h2><p>Hearth 能提出可执行的主动建议，说明触发原因、建议动作、预算和是否会打扰用户。</p><p>Stage 4 的价值不是后台运行，而是在正确的时间以可接受的打扰做正确的事。主动性必须建立在既有恢复与审批之上。</p><h2 id="开始前" tabindex="-1">开始前 <a class="header-anchor" href="#开始前" aria-label="Permalink to &quot;开始前&quot;">​</a></h2><ul><li>Stage 1–3 的恢复、审批、验证、接管和撤销已经稳定。</li><li>已明确允许触发主动任务的来源、时间窗口、预算和静默时段。</li><li>手机只作为查看、审批、接管和发起入口，不成为默认执行权威。</li></ul><h2 id="四个实施工作包" tabindex="-1">四个实施工作包 <a class="header-anchor" href="#四个实施工作包" aria-label="Permalink to &quot;四个实施工作包&quot;">​</a></h2><blockquote><p>每个工作包都要产生可运行的代码、可复现的验证或明确的界面结果；只写接口或只做页面都不算完成。</p></blockquote><h3 id="_01-·-trigger-接入与去重" tabindex="-1">01 · Trigger 接入与去重 <a class="header-anchor" href="#_01-·-trigger-接入与去重" aria-label="Permalink to &quot;01 · Trigger 接入与去重&quot;">​</a></h3><p>先接邮件、日历、文件变化或任务依赖中的一种真实 Trigger，保存来源事件、观察时间、作用域和去重键。乱序、重复和延迟事件按业务键合并；来源失效、权限撤销或时间过旧时不生成候选，并记录忽略原因。</p><h3 id="_02-·-候选生成与自主级别" tabindex="-1">02 · 候选生成与自主级别 <a class="header-anchor" href="#_02-·-候选生成与自主级别" aria-label="Permalink to &quot;02 · 候选生成与自主级别&quot;">​</a></h3><p>候选生成必须引用一条真实触发事件和明确用户目标，输出为什么现在、建议动作、风险、预算和过期时间。A1 只建议、A2 可执行低风险可逆动作，A3 及以上仍逐次审批；候选本身不携带任何新增权限。</p><h3 id="_03-·-主动任务卡与为什么现在" tabindex="-1">03 · 主动任务卡与为什么现在 <a class="header-anchor" href="#_03-·-主动任务卡与为什么现在" aria-label="Permalink to &quot;03 · 主动任务卡与为什么现在&quot;">​</a></h3><p>主动收件箱展示来源、触发时间、与用户目标的关系、建议动作和忽略后的结果。用户可以一键查看证据、暂停、忽略、降低自主级别或转为手动任务；没有来源的“智能建议”不得进入收件箱。</p><h3 id="_04-·-预算、降级与循环保护" tabindex="-1">04 · 预算、降级与循环保护 <a class="header-anchor" href="#_04-·-预算、降级与循环保护" aria-label="Permalink to &quot;04 · 预算、降级与循环保护&quot;">​</a></h3><p>为每个 Trigger 设置频率、并发、Token、外部动作和打断预算，达到上限立即停止。相同来源在冷却窗口内只产生一个候选，连续低价值候选自动降级；验收要覆盖重复事件、预算耗尽、撤销权限和 runaway loop。</p><h2 id="工程落点" tabindex="-1">工程落点 <a class="header-anchor" href="#工程落点" aria-label="Permalink to &quot;工程落点&quot;">​</a></h2><h3 id="主要目录与模块" tabindex="-1">主要目录与模块 <a class="header-anchor" href="#主要目录与模块" aria-label="Permalink to &quot;主要目录与模块&quot;">​</a></h3><ul><li><code>apps/hearthd/triggers</code> — Trigger 适配器、去重键、候选生成与降级</li><li><code>packages/control</code> — 自主级别、候选策略、风险门槛与 kill switch</li><li><code>packages/attention</code> — 注意力预算、静默时段、通知聚合与价值评分</li><li><code>apps/pwa</code> — 移动任务卡、审批、接管、离线只读与推送入口</li><li><code>packages/devices/pairing</code> — 公钥配对、短期会话与远程撤销</li><li><code>packages/relay</code> — 端到端加密推送、最小元数据与重放防护</li><li><code>apps/web</code> — 为什么现在、主动收件箱、强度设置与中断历史</li></ul><h3 id="关键接口" tabindex="-1">关键接口 <a class="header-anchor" href="#关键接口" aria-label="Permalink to &quot;关键接口&quot;">​</a></h3><table tabindex="0"><thead><tr><th>接口</th><th>必须保持的契约</th></tr></thead><tbody><tr><td><code>TriggerEvent</code></td><td>triggerId、source、dedupeKey、observedAt、payloadRef、scope、sensitivity；重复事件不能生成重复任务。</td></tr><tr><td><code>ProactiveCandidate</code></td><td>candidateId、whyNow、proposedAction、autonomyLevel、risk、budget、expiresAt；候选不是授权。</td></tr><tr><td><code>AttentionBudget</code></td><td>window、maxInterruptions、quietHours、valueThreshold、spent；预算耗尽必须停止主动打扰。</td></tr><tr><td><code>MobileApproval</code></td><td>approvalId、nonce、parameterHash、expiresAt、deviceId、signature；离线状态不得确认外部副作用。</td></tr></tbody></table><h3 id="共享验证命令" tabindex="-1">共享验证命令 <a class="header-anchor" href="#共享验证命令" aria-label="Permalink to &quot;共享验证命令&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:triggers：重复事件、乱序、失效来源和预算耗尽</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:attention：静默时段、聚合、疲劳阈值和</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kill</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> switch</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:pwa：离线、断网、生物识别、重放和远程撤销</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eval:proactive：主动与手动对照的成功率、打断和满意度</span></span></code></pre></div><h2 id="验收演练" tabindex="-1">验收演练 <a class="header-anchor" href="#验收演练" aria-label="Permalink to &quot;验收演练&quot;">​</a></h2><ol><li>从干净的数据目录启动 hearthd，打开 <a href="/hearth-os/delivery/stage-4/d4-1.html">D4.1 页面</a>，确认当前页面没有依赖浏览器缓存或手工种子数据。</li><li>按顺序完成四个工作包：Trigger 接入与去重、候选生成与自主级别、主动任务卡与为什么现在、预算、降级与循环保护。每完成一个工作包，保存对应测试输出、截图或产物版本。</li><li>复现失败案例“重复触发导致通知轰炸”。页面必须显示“聚合为一个候选卡并标注重复来源。”，然后按“提高去重窗口、暂停触发或降低主动级别。”恢复；不得出现重复副作用或未登记状态。</li><li>重启服务并重新打开任务，确认运行状态、审批、产物和恢复入口都来自持久投影，而不是只存在于当前页面。</li><li>运行上方的共享验证命令并导出证据。完成门槛是：重复事件不生成重复任务；主动建议有来源；用户能一键暂停；没有无限后台循环；预算耗尽会停止；高风险动作仍需审批。</li></ol><h2 id="交付物" tabindex="-1">交付物 <a class="header-anchor" href="#交付物" aria-label="Permalink to &quot;交付物&quot;">​</a></h2><ul><li>Trigger 目录与去重演示</li><li>主动收件箱</li><li>为什么现在解释</li><li>暂停/预算停止测试</li></ul><h2 id="完成判定" tabindex="-1">完成判定 <a class="header-anchor" href="#完成判定" aria-label="Permalink to &quot;完成判定&quot;">​</a></h2><ul><li>[ ] 重复事件不生成重复任务；主动建议有来源；用户能一键暂停；没有无限后台循环；预算耗尽会停止；高风险动作仍需审批。</li><li>[ ] 交付物已经和契约、任务卡投影保持一致，没有未登记的字段或状态。</li><li>[ ] 至少一个失败路径有可操作恢复，关键动作留下审计事件。</li><li>[ ] 演示不依赖手工修改数据库、只在终端拼接命令，或永久 mock。</li></ul><h2 id="失败与恢复" tabindex="-1">失败与恢复 <a class="header-anchor" href="#失败与恢复" aria-label="Permalink to &quot;失败与恢复&quot;">​</a></h2><table tabindex="0"><thead><tr><th>情况</th><th>用户看到</th><th>恢复动作</th></tr></thead><tbody><tr><td>重复触发导致通知轰炸</td><td>聚合为一个候选卡并标注重复来源。</td><td>提高去重窗口、暂停触发或降低主动级别。</td></tr><tr><td>手机审批被重放</td><td>审批拒绝并显示设备/时间不匹配。</td><td>要求重新认证并重新生成审批请求。</td></tr><tr><td>后台预算耗尽</td><td>主动任务停在预算边界，显示已停止原因。</td><td>等待用户提高预算或手动继续，不自动透支。</td></tr></tbody></table><h2 id="本增量不包含" tabindex="-1">本增量不包含 <a class="header-anchor" href="#本增量不包含" aria-label="Permalink to &quot;本增量不包含&quot;">​</a></h2><ul><li>不在没有恢复、审批和验证的前提下开放主动循环。</li><li>不为了活跃度制造任务或通知。</li><li>不把手机变成长期持有主凭据的执行设备。</li></ul><h2 id="来源与下一步" tabindex="-1">来源与下一步 <a class="header-anchor" href="#来源与下一步" aria-label="Permalink to &quot;来源与下一步&quot;">​</a></h2><h3 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h3><ul><li><a href="/hearth-os/architecture/control-plane.html">控制面与自主性</a></li><li><a href="/hearth-os/architecture/gateway.html">个人网关</a></li><li><a href="/hearth-os/architecture/security-privacy.html">安全与隐私</a></li><li><a href="/hearth-os/architecture/frontend-experience.html">前端与移动体验</a></li></ul><h3 id="完成后的下一步" tabindex="-1">完成后的下一步 <a class="header-anchor" href="#完成后的下一步" aria-label="Permalink to &quot;完成后的下一步&quot;">​</a></h3><p>继续 <a href="/hearth-os/delivery/stage-4/d4-2.html">D4.2 · 手机 PWA：查看、审批、接管和发起</a>。先完成本增量验收，不要用后续工作掩盖当前缺口。</p>`,42)])])}const g=e(l,[["render",d]]);export{u as __pageData,g as default};
